CREATE TABLE IF NOT EXISTS system_lock (id INT PRIMARY KEY);
INSERT INTO system_lock SELECT 1 WHERE NOT EXISTS (SELECT 1 FROM system_lock);
CREATE TABLE IF NOT EXISTS users (id VARCHAR(64) PRIMARY KEY, phone VARCHAR(32) UNIQUE NOT NULL, name VARCHAR(128) NOT NULL, pin_hash VARCHAR(256) NOT NULL, role VARCHAR(24) NOT NULL, device_id VARCHAR(128), birth_date VARCHAR(32), created_at VARCHAR(40) NOT NULL, failed_attempts INT DEFAULT 0, locked_until BIGINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (token VARCHAR(128) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, device_id VARCHAR(128) NOT NULL, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS accounts (id VARCHAR(128) PRIMARY KEY, normal_side VARCHAR(1) NOT NULL);
CREATE TABLE IF NOT EXISTS journal (id VARCHAR(64) PRIMARY KEY, business_type VARCHAR(32) NOT NULL, description VARCHAR(256), created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS postings (id VARCHAR(64) PRIMARY KEY, journal_id VARCHAR(64) NOT NULL REFERENCES journal(id), account_id VARCHAR(128) NOT NULL REFERENCES accounts(id), direction VARCHAR(1) NOT NULL CHECK(direction IN ('D','C')), amount BIGINT NOT NULL CHECK(amount > 0));
CREATE TABLE IF NOT EXISTS holds (id VARCHAR(64) PRIMARY KEY, account_id VARCHAR(128) NOT NULL, amount BIGINT NOT NULL CHECK(amount>0), status VARCHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS records (id VARCHAR(64) PRIMARY KEY, kind VARCHAR(40) NOT NULL, owner_id VARCHAR(64) NOT NULL, body TEXT NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE INDEX IF NOT EXISTS records_kind_owner ON records(kind,owner_id);
CREATE TABLE IF NOT EXISTS idempotency (user_id VARCHAR(64), idem_key VARCHAR(128), fingerprint TEXT NOT NULL, response TEXT NOT NULL, PRIMARY KEY(user_id,idem_key));
CREATE TABLE IF NOT EXISTS audit_log (id VARCHAR(64) PRIMARY KEY, actor VARCHAR(64), action VARCHAR(128), body TEXT, created_at VARCHAR(40));
